def normalize_language(language):
    code = (language or "").strip().lower()
    return code if code in SUPPORTED_LANGUAGES else DEFAULT_LANGUAGE

def family_language(family):
    return normalize_language(getattr(family, "language", None))

def t(language, key, **kwargs):
    code = normalize_language(language)
    template = OVERRIDES.get(code, {}).get(key, RU.get(key, key))
    return template.format(**kwargs) if kwargs else template

def all_texts(key):
    return {t(language, key) for language in SUPPORTED_LANGUAGES}

def category_label(language, stored_category):
    if not stored_category:
        return ""
    parts = stored_category.split(maxsplit=1)
    if len(parts) != 2:
        return stored_category
    icon, label = parts
    return f"{icon} {CATEGORY_LABELS.get(label, {}).get(normalize_language(language), label)}"

def month_name(language, month):
    names = MONTH_NAMES.get(normalize_language(language), MONTH_NAMES[DEFAULT_LANGUAGE])
    return names[month] if 1 <= month <= 12 else ""
